import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    prev = -1
    out = []
    for t in data[1:1 + n]:
        L = len(t)
        if L == 1:
            cands = {int(t)}
        else:
            cands = {int(t[i:j]) for i in range(L) for j in range(i + 1, L + 1)}
        best = -1
        for v in cands:
            if v >= prev and (best < 0 or v < best):
                best = v
        if best < 0:
            print(-1)
            return
        out.append(best)
        prev = best
    print(' '.join(map(str, out)))

