from itertools import product

data = sys.stdin.read().split()
n = int(data[0])
opts = []
for t in data[1:1 + n]:
    s = {int(t)}
    if len(t) > 1:
        for i in range(len(t)):
            for j in range(i + 1, len(t) + 1):
                s.add(int(t[i:j]))
    opts.append(sorted(s))
best = None
for combo in product(*opts):
    if all(combo[i] <= combo[i + 1] for i in range(n - 1)):
        if best is None or combo < best:
            best = combo
print(' '.join(map(str, best)) if best else -1)

